public async Task FormatterTypesAreExcludedFromCodeCoverageButResolversAreNot()
{
    IReadOnlyList<(string Path, string Text)> generated = await RunGeneratorAsync(TestSource);

    // Formatters for objects (both integer and string keyed), the enum and union, plus the resolver.
    string paths = string.Join(Environment.NewLine, generated.Select(g => g.Path));
    Assert.True(generated.Count >= 5, $"Expected generated formatters and resolver, got:{Environment.NewLine}{paths}");

    bool foundResolver = false;
    foreach ((string path, string text) in generated)
    {
        if (text.Contains(": MsgPack::IFormatterResolver"))
        {
            foundResolver = true;
            Assert.False(text.Contains(ExcludeAttribute), $"Generated resolver '{path}' should not have {ExcludeAttribute}.");
            continue;
        }

        Assert.True(
            text.Contains(ExcludeAttribute),
            $"Generated formatter file '{path}' is missing {ExcludeAttribute}.");
    }

    Assert.True(foundResolver, $"Expected a generated resolver, got:{Environment.NewLine}{paths}");
}

